package org.springframework.samples.petclinic.acceptance;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** A new owner's membershipLevel is capped at one above the highest level among its household members. */
class MembershipLevelCapTest extends AcceptanceBase {

	@Test
	void capsLevelAtOneAboveHouseholdMaximum() throws Exception {
		String lastName = uniqueLastName();
		// Two level-1 members: no email, no namesakes -> 1 point.
		for (int i = 0; i < 2; i++) {
			ObjectNode member = structuredOwner();
			member.put("lastName", lastName);
			member.put("sharesHousehold", true);
			assertEquals(1, fetchOwner(createOwnerOk(member)).get("membershipLevel").asInt());
		}
		// Email (2) + no namesakes (1) + household of 3 (2) = 5 points -> level 3, capped to 2.
		ObjectNode third = structuredOwner();
		third.put("lastName", lastName);
		third.put("email", uniqueEmail());
		third.put("sharesHousehold", true);
		JsonNode created = fetchOwner(createOwnerOk(third));
		assertEquals(5, created.get("membershipPoints").asInt());
		assertEquals(2, created.get("membershipLevel").asInt());
	}

	@Test
	void noCapWithoutHouseholdMembers() throws Exception {
		ObjectNode owner = structuredOwner();
		owner.put("email", uniqueEmail());
		// Email (2) + no namesakes (1) = 3 points -> level 2, more than one above the (absent) household.
		assertEquals(2, fetchOwner(createOwnerOk(owner)).get("membershipLevel").asInt());
	}
}

